import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 49 The ideal servant","description":"学习 介词加关系代词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 49 The ideal servant","description":"学习 介词加关系代词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 介词加关系代词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 48 The silent village","link":"/life/english/new-concept/book-3/unit-03/lesson-048"},"next":{"text":"第三册：培养技能 · Lesson 50 New Year resolutions","link":"/life/english/new-concept/book-3/unit-03/lesson-050"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 48 The silent village","link":"/life/english/new-concept/book-3/unit-03/lesson-048"},"next":{"text":"第三册：培养技能 · Lesson 50 New Year resolutions","link":"/life/english/new-concept/book-3/unit-03/lesson-050"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-049.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-049.md"}'),l={name:"life/english/new-concept/book-3/unit-03/lesson-049.md"};function i(r,e,s,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-49-the-ideal-servant" tabindex="-1">第三册：培养技能 · Lesson 49 The ideal servant <a class="header-anchor" href="#第三册-培养技能-·-lesson-49-the-ideal-servant" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 49 The ideal servant&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从理想服务与实际相处的差距学习评价标准。所谓理想往往反映雇主个人期望，需要说明标准而不是让标签替代事实。学习关系从句中的介词位置和 whom 的用法，在正式与日常表达之间作合适选择，并保证动词介词搭配完整。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>reliable</td><td>/rɪˈlaɪəbl/</td><td>adj.</td><td>可靠的</td><td>a reliable assistant</td></tr><tr><td>expectation</td><td>/ˌekspekˈteɪʃən/</td><td>n.</td><td>期望</td><td>clear expectations</td></tr><tr><td>routine</td><td>/ruːˈtiːn/</td><td>n.</td><td>常规</td><td>a daily routine</td></tr><tr><td>considerate</td><td>/kənˈsɪdərət/</td><td>adj.</td><td>体贴的</td><td>a considerate colleague</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>rely on — 依靠</li><li>live up to — 达到期望或标准</li></ul><h2 id="语法讲解-介词加关系代词" tabindex="-1">语法讲解：介词加关系代词 <a class="header-anchor" href="#语法讲解-介词加关系代词" aria-label="Permalink to &quot;语法讲解：介词加关系代词&quot;">​</a></h2><p>正式表达可将介词放在 whom 或 which 前，如 the person on whom we rely；日常表达常把介词留在从句末尾，如 the person we rely on。介词前置时不能使用 that，也不能省略 whom 或 which。选择哪个介词取决于 rely on、speak to 等实际搭配，而非关系词本身。whose 表所属，不能用来代替所有介词结构。写人物关系时，正式程度不是唯一目标，读者是否能准确识别责任与依赖关系更重要。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The assistant on whom the household relied kept a careful record of every delivery.</p></blockquote><p>全家依靠的那位助手仔细记录了每次送货。</p><p>on whom 引导限定从句，on 来自 rely on；从句修饰 assistant。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>the person on that we rely 不成立，介词前置需用 whom；或写 the person that we rely on。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照朗读 on whom we rely 与 whom we rely on，检查 on 是否保留；随后用更自然的口语形式复述示范。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The coordinator on whom we rely checks every booking twice. She also explains changes before they affect visitors. Clear communication matters more to us than a flawless appearance.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句说明一位虚构助手的可靠性，给出可观察行为。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>具体行动支撑可靠评价，最后一句明确价值标准。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>把例句的关系从句改为介词留末尾的形式。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The assistant whom the household relied on kept a careful record of every delivery.</p><p><strong>解析：</strong> on 移到 relied 后，whom 也可省略。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：the system ___ which we depend</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> on</p><p><strong>解析：</strong> 搭配为 depend on。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>介词前置时能省去 whom 吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 介词需要明确关系代词宾语。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：介词加关系代词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-048">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-050">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(l,[["render",i]]);export{u as __pageData,b as default};
